/**
 * Lightweight pure-JS ZIP Archive Builder
 * Implements JSZip compatible API for extension background workers and content scripts.
 * Supports scoped subfolders and zero-copy chunked Blob generation for large multi-chapter archives.
 */
(function(global) {
  'use strict';

  // CRC32 Lookup Table (IEEE 802.3 standard)
  const crcTable = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    crcTable[i] = c >>> 0;
  }

  function computeCRC32(uint8Array) {
    if (!uint8Array || uint8Array.length === 0) return 0;
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < uint8Array.length; i++) {
      crc = (crc >>> 8) ^ crcTable[(crc ^ uint8Array[i]) & 0xFF];
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
  }

  // Valid default MS-DOS Date & Time (2026-01-01 12:00:00)
  // Time: (12 << 11) | (0 << 5) | 0 = 0x6000
  // Date: ((2026 - 1980) << 9) | (1 << 5) | 1 = (46 << 9) | 32 | 1 = 0x5C21
  const DOS_TIME_DEFAULT = 0x6000;
  const DOS_DATE_DEFAULT = 0x5C21;

  class JSZip {
    constructor(root = null, prefix = '') {
      this.root = root || this;
      this.prefix = prefix || '';
      this.files = root ? root.files : {};
    }

    file(name, data, options = {}) {
      if (!name) return null;
      const cleanName = name.startsWith('/') ? name.slice(1) : name;
      const fullPath = this.prefix + cleanName;

      // 1-argument call: getter
      if (arguments.length === 1 || data === undefined) {
        return this.root.files[fullPath] || null;
      }

      // null data: delete entry
      if (data === null) {
        delete this.root.files[fullPath];
        return this;
      }

      this.root.files[fullPath] = {
        name: fullPath,
        data: data,
        options: options || {}
      };
      return this;
    }

    folder(name) {
      if (!name) return this;
      let cleanName = name.startsWith('/') ? name.slice(1) : name;
      if (!cleanName.endsWith('/')) cleanName += '/';
      const fullPath = this.prefix + cleanName;

      if (!this.root.files[fullPath]) {
        this.root.files[fullPath] = {
          name: fullPath,
          data: new Uint8Array(0),
          options: { dir: true }
        };
      }
      return new JSZip(this.root, fullPath);
    }

    async generateAsync(options = { type: 'blob' }, onProgress = null) {
      const targetFiles = this.root.files;
      const fileKeys = Object.keys(targetFiles);
      const entries = [];
      let currentOffset = 0;

      const encoder = new TextEncoder();

      for (let i = 0; i < fileKeys.length; i++) {
        const key = fileKeys[i];
        const item = targetFiles[key];

        let rawData = item.data;
        if (rawData && typeof rawData.then === 'function') {
          rawData = await rawData;
        }

        let contentBytes;
        if (rawData instanceof Uint8Array) {
          contentBytes = rawData;
        } else if (ArrayBuffer.isView(rawData)) {
          contentBytes = new Uint8Array(rawData.buffer, rawData.byteOffset, rawData.byteLength);
        } else if (rawData instanceof ArrayBuffer || (rawData && rawData.byteLength !== undefined && typeof rawData.slice === 'function')) {
          contentBytes = new Uint8Array(rawData);
        } else if (typeof Blob !== 'undefined' && rawData instanceof Blob) {
          const ab = await rawData.arrayBuffer();
          contentBytes = new Uint8Array(ab);
        } else if (typeof rawData === 'string') {
          contentBytes = encoder.encode(rawData);
        } else {
          contentBytes = new Uint8Array(0);
        }

        const isDir = (item.options && item.options.dir) || item.name.endsWith('/');
        if (isDir) {
          contentBytes = new Uint8Array(0);
        }

        const nameBytes = encoder.encode(item.name);
        const crc = isDir ? 0 : computeCRC32(contentBytes);
        const uncompressedSize = isDir ? 0 : contentBytes.length;
        const compressedSize = uncompressedSize; // Store (no compression)

        // Local Header (30 bytes + name length)
        // Offset  Size  Description
        // 0       4     Local file header signature = 0x04034b50
        // 4       2     Version needed to extract = 20 (2.0)
        // 6       2     General purpose bit flag = 0x0800 (bit 11 = UTF-8)
        // 8       2     Compression method = 0 (Store)
        // 10      2     Last mod file time
        // 12      2     Last mod file date
        // 14      4     CRC-32
        // 18      4     Compressed size
        // 22      4     Uncompressed size
        // 26      2     File name length
        // 28      2     Extra field length = 0
        // 30      n     File name
        const localHeader = new Uint8Array(30 + nameBytes.length);
        const view = new DataView(localHeader.buffer);

        view.setUint32(0, 0x04034b50, true);
        view.setUint16(4, 20, true);
        view.setUint16(6, 0x0800, true); // UTF-8 filename flag
        view.setUint16(8, 0, true);      // Store
        view.setUint16(10, DOS_TIME_DEFAULT, true);
        view.setUint16(12, DOS_DATE_DEFAULT, true);
        view.setUint32(14, crc, true);
        view.setUint32(18, compressedSize, true);
        view.setUint32(22, uncompressedSize, true);
        view.setUint16(26, nameBytes.length, true);
        view.setUint16(28, 0, true);

        localHeader.set(nameBytes, 30);

        entries.push({
          name: item.name,
          nameBytes: nameBytes,
          isDir: isDir,
          crc: crc,
          compressedSize: compressedSize,
          uncompressedSize: uncompressedSize,
          localHeaderOffset: currentOffset,
          localHeader: localHeader,
          contentBytes: contentBytes
        });

        currentOffset += localHeader.length + contentBytes.length;

        if (onProgress && typeof onProgress === 'function') {
          onProgress({ percent: Math.round(((i + 1) / fileKeys.length) * 100) });
        }
      }

      // Build Central Directory Headers
      let centralDirSize = 0;
      const centralDirHeaders = [];

      for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];
        // Central Header Size: 46 + nameBytes.length
        // Offset  Size  Description
        // 0       4     Central file header signature = 0x02014b50
        // 4       2     Version made by = 0x0314 (Unix 2.0)
        // 6       2     Version needed to extract = 20 (2.0)
        // 8       2     General purpose bit flag = 0x0800 (UTF-8)
        // 10      2     Compression method = 0 (Store)
        // 12      2     Last mod file time
        // 14      2     Last mod file date
        // 16      4     CRC-32 (CRITICAL: 4 bytes / setUint32!)
        // 20      4     Compressed size
        // 24      4     Uncompressed size
        // 28      2     File name length
        // 30      2     Extra field length = 0
        // 32      2     File comment length = 0
        // 34      2     Disk number start = 0
        // 36      2     Internal file attributes = 0
        // 38      4     External file attributes (0x41ED0010 for dir, 0x81A40000 for file)
        // 42      4     Relative offset of local header
        // 46      n     File name
        const cdHeader = new Uint8Array(46 + entry.nameBytes.length);
        const view = new DataView(cdHeader.buffer);

        view.setUint32(0, 0x02014b50, true);
        view.setUint16(4, 0x0314, true); // Version made by: Unix 2.0
        view.setUint16(6, 20, true);     // Version needed: 2.0
        view.setUint16(8, 0x0800, true); // UTF-8 filename flag
        view.setUint16(10, 0, true);     // Store
        view.setUint16(12, DOS_TIME_DEFAULT, true);
        view.setUint16(14, DOS_DATE_DEFAULT, true);
        view.setUint32(16, entry.crc, true); // 32-bit CRC-32!
        view.setUint32(20, entry.compressedSize, true);
        view.setUint32(24, entry.uncompressedSize, true);
        view.setUint16(28, entry.nameBytes.length, true);
        view.setUint16(30, 0, true);
        view.setUint16(32, 0, true);
        view.setUint16(34, 0, true);
        view.setUint16(36, 0, true);

        // External attributes: Unix permissions in high 16 bits, DOS attrs in low 16 bits
        // Directory: drwxr-xr-x (0o040755 = 0x41ED) | DOS directory attr (0x10) -> 0x41ED0010
        // File:      -rw-r--r-- (0o100644 = 0x81A4) | 0x00                     -> 0x81A40000
        const externalAttrs = entry.isDir ? 0x41ED0010 : 0x81A40000;
        view.setUint32(38, externalAttrs, true);
        view.setUint32(42, entry.localHeaderOffset, true);

        cdHeader.set(entry.nameBytes, 46);
        centralDirHeaders.push(cdHeader);
        centralDirSize += cdHeader.length;
      }

      const centralDirStartOffset = currentOffset;

      // End of Central Directory Record (EOCD: 22 bytes)
      // Offset  Size  Description
      // 0       4     EOCD signature = 0x06054b50
      // 4       2     Disk number = 0
      // 6       2     Start disk = 0
      // 8       2     Records on this disk
      // 10      2     Total records
      // 12      4     Size of central directory
      // 16      4     Offset of central directory
      // 20      2     Comment length = 0
      const eocd = new Uint8Array(22);
      const eocdView = new DataView(eocd.buffer);

      eocdView.setUint32(0, 0x06054b50, true);
      eocdView.setUint16(4, 0, true);
      eocdView.setUint16(6, 0, true);
      eocdView.setUint16(8, entries.length, true);
      eocdView.setUint16(10, entries.length, true);
      eocdView.setUint32(12, centralDirSize, true);
      eocdView.setUint32(16, centralDirStartOffset, true);
      eocdView.setUint16(20, 0, true);

      // Memory-efficient streaming chunk array:
      // Blob accepts array of chunks without requiring one giant contiguous ArrayBuffer.
      // This prevents RangeError: Array buffer allocation failed on large multi-chapter archives.
      if (options.type === 'blob') {
        const chunks = [];
        for (let i = 0; i < entries.length; i++) {
          chunks.push(entries[i].localHeader);
          if (entries[i].contentBytes.length > 0) {
            chunks.push(entries[i].contentBytes);
          }
        }
        for (let i = 0; i < centralDirHeaders.length; i++) {
          chunks.push(centralDirHeaders[i]);
        }
        chunks.push(eocd);
        return new Blob(chunks, { type: 'application/zip' });
      }

      // Fallback for uint8array / arraybuffer requests
      const totalSize = centralDirStartOffset + centralDirSize + 22;
      const finalZip = new Uint8Array(totalSize);
      let pos = 0;

      for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];
        finalZip.set(entry.localHeader, pos);
        pos += entry.localHeader.length;
        if (entry.contentBytes.length > 0) {
          finalZip.set(entry.contentBytes, pos);
          pos += entry.contentBytes.length;
        }
      }

      for (let i = 0; i < centralDirHeaders.length; i++) {
        finalZip.set(centralDirHeaders[i], pos);
        pos += centralDirHeaders[i].length;
      }

      finalZip.set(eocd, pos);

      if (options.type === 'uint8array') {
        return finalZip;
      } else if (options.type === 'arraybuffer') {
        return finalZip.buffer;
      }
      return new Blob([finalZip], { type: 'application/zip' });
    }
  }

  global.JSZip = JSZip;
})(typeof self !== 'undefined' ? self : this);
